import java.util.Scanner;

public class Main {

    public static boolean isPrime(int n) {
        // 小于2不是质数
        if (n < 2) {
            return false;
        }
        // 2是质数
        if (n == 2) {
            return true;
        }
        // 大于2的偶数不是质数
        if (n % 2 == 0) {
            return false;
        }

        // 只判断奇数因子，枚举到 sqrt(n)
        for (int i = 3; (long) i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }

    public static int nearestPrime(int x) {
        // 按距离从小到大枚举
        int d = 0;
        while (true) {
            int left = x - d;
            int right = x + d;

            // 先判断左边，保证等距离时取较小者
            if (isPrime(left)) {
                return left;
            }
            if (d != 0 && isPrime(right)) {
                return right;
            }

            d++;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int t = sc.nextInt();
        while (t-- > 0) {
            int x = sc.nextInt();
            System.out.println(nearestPrime(x));
        }

        sc.close();
    }
}
